#!/bin/bash
set -euo pipefail

# =============================================================================
# Detailed documentation: combine_picard_qc_metrics.sh
# Purpose: This pipeline helper script aggregates QC metrics generated by Picard
#   (specifically HsMetrics and InsertSizeMetrics) across multiple samples in the
#   working directory. It parses output files, extracts key metrics, and merges
#   them into a single consolidated tab-separated file (`qcs_metrics`).
#
# Inputs:
#   - *.hs_metrics.txt: Picard Hybrid Selection (HS) metrics files for each sample.
#   - *.insert_size_metrics.txt: Picard Insert Size metrics files for each sample.
#
# Outputs:
#   - hs_metrics.txt: Intermediate file containing combined HS metrics.
#   - insert_size_metrics.txt: Intermediate file containing combined insert size metrics.
#   - qcs_metrics: Final output file joining the metrics of interest on Sample ID.
#
# Extracted HS Metrics Columns (mapped via awk field indexes):
#   - $9:  PCT_PF_UQ_READS - Fraction of PF reads that align to the bait or near-bait regions.
#   - $32: AT_DROPOUT - A measure of dropout rate in AT-rich regions.
#   - $48: GC_DROPOUT - A measure of dropout rate in GC-rich regions.
#   - $52: ON_BAIT_VS_SELECTED - Ratio of on-bait bases to bases in selected regions.
#   - $63: PCT_TARGET_BASES_10X - Fraction of target bases covered at >= 10X.
#   - $64: PCT_TARGET_BASES_50X - Fraction of target bases covered at >= 50X.
#
# Extracted Insert Size Metrics Columns:
#   - $6:  MEDIAN_INSERT_SIZE - The median insert size of the paired-end reads.
# =============================================================================

shopt -s nullglob
hs_files=( *.hs_metrics.txt )
ins_files=( *.insert_size_metrics.txt )

if [ ${#hs_files[@]} -eq 0 ] && [ ${#ins_files[@]} -eq 0 ]; then
    echo -e "SAMPLE\tPCT_PF_UQ_READS\tAT_DROPOUT\tGC_DROPOUT\tON_BAIT_VS_SELECTED\tPCT_TARGET_BASES_10X\tPCT_TARGET_BASES_50X\tMEDIAN_INSERT_SIZE" > qcs_metrics
    exit 0
fi

## GET FILE HEADERS
# 1. Look for the line following "## METRICS CLASS" in all *.hs_metrics.txt files.
# 2. Filter out any header lines containing "## METRICS CLASS".
# 3. Use uniq to get a single header line.
# 4. Format and output the selected columns (SAMPLE, and Picard HS metrics columns).
if [ ${#hs_files[@]} -gt 0 ]; then
    grep -A1 "## METRICS CLASS" "${hs_files[0]}" | grep -v "## METRICS CLASS" | head -1 | awk -v OFS="\t" '{ print "SAMPLE",$9,$32,$48,$52,$63,$64 }' > hs_metrics.txt
else
    echo -e "SAMPLE\tPCT_PF_UQ_READS\tAT_DROPOUT\tGC_DROPOUT\tON_BAIT_VS_SELECTED\tPCT_TARGET_BASES_10X\tPCT_TARGET_BASES_50X" > hs_metrics.txt
fi

# 1. Repeat the header extraction process for all *.insert_size_metrics.txt files.
# 2. Format and output the selected columns (SAMPLE, and MEDIAN_INSERT_SIZE).
if [ ${#ins_files[@]} -gt 0 ]; then
    grep -A1 "## METRICS CLASS" "${ins_files[0]}" | grep -v "## METRICS CLASS" | head -1 | awk -v OFS="\t" '{ print "SAMPLE",$6}' > insert_size_metrics.txt
else
    echo -e "SAMPLE\tMEDIAN_INSERT_SIZE" > insert_size_metrics.txt
fi

## PRINT OUT FOR HS METRICS
# Iterate over each sample's HS metrics file and extract the data lines.
for hs_metrics in *.hs_metrics.txt
do
    # Extract the sample name from the file name (stripping the suffix)
    sample="${hs_metrics%.hs_metrics.txt}"
    # Print the lines starting from BAIT_SET up to the first empty line,
    # strip the first (header) and last (empty) lines, and then format fields with sample name prefix.
    sed -n '/^BAIT_SET\(.*\)$/,/^$/p' $hs_metrics |\
        sed '1d;$d' | awk -v OFS="\t" -v sample="$sample" '{ print sample,$9,$32,$48,$52,$63,$64 }'
done >> hs_metrics.txt

## PRINT OUT FOR INSERT SIZE METRICS
# Iterate over each sample's insert size metrics file and extract the data lines.
for ins_metrics in *.insert_size_metrics.txt
do
    # Extract the sample name from the file name (stripping the suffix)
    sample="${ins_metrics%.insert_size_metrics.txt}"
    # Print the lines starting from MEDIAN_INSERT_SIZE up to the first empty line,
    # strip the header and trailing empty line, and print sample along with median insert size.
    sed -n '/^MEDIAN_INSERT_SIZE\(.*\)$/,/^$/p' $ins_metrics |\
        sed '1d;$d' | awk -v OFS="\t" -v sample="$sample" '{ print sample,$6}'
done >> insert_size_metrics.txt

# Join the HS metrics and insert size metrics using awk on the sample name (first field).
# In the first file (hs_metrics.txt), map the sample names to their corresponding lines.
# In the second file, if the sample is found in the map, print the HS metrics followed by the insert size metric.
awk -F'\t' -v OFS='\t' 'NR==FNR {a[$1]=$0; next} $1 in a {print a[$1], $2}' hs_metrics.txt insert_size_metrics.txt > qcs_metrics
